    """Return {"budget_consumed": float, "alerts": {severity: [minute, ...]}}."""
    budget = 1 - slo
    rates = [(t - g) / t if t else 0.0 for g, t in minutes]
    consumed = sum(rates) / budget / period_minutes
    alerts = {sev: [] for sev, *_ in rules}
    for sev, long, short, thr in rules:
